 "Referans not: Üst Jüri (Supervisor) kontrol notu — SJDA, SJDB, SJA, SJE. SJ notu yoksa panel sonucu kullanılır (DA/DB ortak not, A/E ortadaki iki kesintinin ortalaması).":"Reference score: Superior Jury (Supervisor) control score — SJDA, SJDB, SJA, SJE. If there is no SJ score, the panel result is used (DA/DB common score, A/E average of the two middle deductions).",
 "Tolerans (Appendix to the CoP §3): DA/DB ±0.50 · A/E referans kesinti 0.00–1.20 → ±0.399, 1.20 üzeri → ±0.699 · aynı paneldeki iki hakem arasında 2.00'den fazla fark blok sebebidir.":"Tolerance (Appendix to the CoP §3): DA/DB ±0.50 · A/E reference deduction 0.00–1.20 → ±0.399, above 1.20 → ±0.699 · a difference of more than 2.00 between two judges in the same panel is grounds for a block.",
 "Başarı %: RG Specific Judges' Rules değerlendirme tabloları — A/E'de sapma ve referans kesinti aralığına (≤2.0 · 2.1–3.5 · ≥3.6) göre; DA/DB'de hata miktarına göre (bireysel DA tablosu daha sıkıdır). Bireysel ve grup için ayrı tablolar.":"Success %: RG Specific Judges' Rules evaluation tables — for A/E by deviation and reference deduction range (≤2.0 · 2.1–3.5 · ≥3.6); for DA/DB by amount of error (the individual DA table is stricter). Separate tables for individual and group.",
 "Not: D için ≥80 Excellent, ≥70 Very Good, ≥60 Good, ≥50 Pass · A/E için ≥90, ≥80, ≥65, ≥50. Eğilim: D'de + yüksek not verme, A/E'de + sert (fazla kesinti).":"Note: for D ≥80 Excellent, ≥70 Very Good, ≥60 Good, ≥50 Pass · for A/E ≥90, ≥80, ≥65, ≥50. Bias: in D + means scoring high, in A/E + means strict (too many deductions).",
 "WG'nin yarışma içi JEP not eşikleri yayımlanmadığından bu karne, WG'nin yayımlanmış tolerans ve değerlendirme tablolarıyla ulusal kullanım için hazırlanmıştır.":"Since WG does not publish its in-competition JEP score thresholds, this report card is prepared for national use with WG's published tolerance and evaluation tables.",
